<!doctype html><html lang="id"><head><meta charset="utf-8"><title><?= html_escape($title) ?></title><style>
@page { size: A4; margin: .5cm; } * { box-sizing: border-box; } body { margin: 0; font-family: Arial, sans-serif; color: #263238; } .sheet { width: 100%; } .head { border-bottom: 3px solid #3157c8; padding-bottom: 14px; margin-bottom: 18px; display: flex; justify-content: space-between; } .brand { color: #3157c8; font-size: 25px; font-weight: bold; } .muted { color: #607d8b; font-size: 12px; } .box { background: #f4f7ff; padding: 14px; margin-bottom: 18px; display: flex; justify-content: space-between; } .box div { width: 24%; } small { display: block; color: #78909c; font-size: 10px; text-transform: uppercase; margin-bottom: 4px; } strong { font-size: 13px; } .columns { display: flex; gap: 18px; } .columns > div { width: 50%; } h3 { font-size: 14px; margin: 0 0 8px; } table { width: 100%; border-collapse: collapse; } th { background: #3157c8; color: #fff; padding: 8px; text-align: left; font-size: 11px; } td { border-bottom: 1px solid #e3e8ef; padding: 8px; font-size: 12px; } .amount { text-align: right; white-space: nowrap; } .summary { width: 280px; margin: 20px 0 0 auto; } .summary td { border: 0; } .net { color: #3157c8; font-size: 16px; font-weight: bold; border-top: 2px solid #3157c8 !important; } @media print { .no-print { display: none; } }
</style></head><body onload="window.print()"><div class="sheet">
<div class="head"><div><div class="brand">SLIP GAJI</div><div class="muted">Dokumen pembayaran gaji karyawan</div></div><div style="text-align:right"><strong><?= html_escape($period_label) ?></strong><div class="muted">Periode pembayaran</div></div></div>
<div class="box"><div><small>Nama Karyawan</small><strong><?= html_escape($employee['name']) ?></strong></div><div><small>Employee Code</small><strong><?= html_escape($employee['employee_code']) ?></strong></div><div><small>Jabatan</small><strong><?= html_escape($employee['position_name'] ?: '-') ?></strong></div><div><small>Departemen</small><strong><?= html_escape($employee['department_name'] ?: '-') ?></strong></div></div>
<div class="columns"><div><h3>Pendapatan</h3><table><thead><tr><th>Komponen</th><th class="amount">Nominal</th></tr></thead><tbody><?php foreach ($earnings as $row): ?><tr><td><?= html_escape($row['component_name']) ?></td><td class="amount"><?= number_format((float) $row['amount'], 0, ',', '.') ?></td></tr><?php endforeach; ?></tbody></table></div><div><h3>Pengurang</h3><table><thead><tr><th>Komponen</th><th class="amount">Nominal</th></tr></thead><tbody><?php foreach ($deductions as $row): ?><tr><td><?= html_escape($row['component_name']) ?></td><td class="amount"><?= number_format((float) $row['amount'], 0, ',', '.') ?></td></tr><?php endforeach; ?></tbody></table></div></div>
<table class="summary"><tr><td>Total Pendapatan</td><td class="amount"><?= number_format((float) $total_earning, 0, ',', '.') ?></td></tr><tr><td>Total Pengurang</td><td class="amount"><?= number_format((float) $total_deduction, 0, ',', '.') ?></td></tr><tr><td class="net">Take Home Pay</td><td class="amount net"><?= number_format((float) $total_earning - (float) $total_deduction, 0, ',', '.') ?></td></tr></table>
</div></body></html>
